/// Reading and writing the selection's properties (spec §4.3). Created once
/// by `InspectorViewController` and handed to every pane; `invalidate()` at
/// the start of each refresh drops the evaluated-state cache so a moved
/// playhead is never read stale.
final class InspectorBinding {
    weak var inspector: InspectorViewController?

    /// Evaluated props per clip, filled lazily. Only a clip with a selected
    /// action (`.end`, `.start`) or with the playhead inside it (`.playhead`)
    /// ever reaches the FFI; everything else reads its base props straight
    /// off the snapshot, and `.defaults` reads neither.
    private var cache: [CacheKey: Evaluated] = [:]

    /// WHEN a read is answered for (road map 9 §5): `.end` is the selected
    /// action's end state (spec §11 CI-2) and what every field shows;
    /// `.start` is the selected action's start, the keyed slider segment's
    /// far end; `.playhead` is the document's playhead whenever it is inside
    /// the clip, whatever is selected — the coral tick and the "now" tag;
    /// `.defaults` is what a row resets to (spec §11 CI-9): the four props
    /// readers answer `VideoProps.identity`, `AudioProps()`, `TextProps()`
    /// and `ShapeProps()`, with no FFI call and no cache entry.
    enum ReadMode: Hashable { case end, start, playhead, defaults }
    private(set) var mode: ReadMode = .end

    /// Runs `read` in `mode` and restores the mode it found.
    func at<T>(_ mode: ReadMode, _ read: () -> T) -> T {
        let saved = self.mode
        self.mode = mode
        defer { self.mode = saved }
        return read()
    }

    init(inspector: InspectorViewController) {
        self.inspector = inspector
    }

    // MARK: Model access

    private func evaluated(_ clip: ClipSnapshot) -> Evaluated {
        let key = CacheKey(clip: clip.id, mode: mode)
        if let cached = cache[key] { return cached }
        var state = Evaluated()
        // At the END tick: the core has merged every action ending there and
        // none starting there has progressed, so this is the end state.
        let time: Ticks?
        switch mode {
        case .end: time = action(clip).map { clip.start + $0.endTime }
        case .start: time = action(clip).map { clip.start + $0.start }
        case .playhead: time = clip.start <= playhead && playhead < clip.end ? playhead : nil
        case .defaults: time = nil
        }
        if let time, let raw = project?.clipState(clip.id, at: time) {
            state.video = InspectorBinding.decode(VideoProps.self, raw["video"])
            state.audio = InspectorBinding.decode(AudioProps.self, raw["audio"])
            state.text = InspectorBinding.decode(TextProps.self, raw["text"])
            state.graphic = InspectorBinding.decode(GraphicSnapshot.self, raw["graphic"])?.props
            state.speed = raw["speed"] as? Double
        }
        cache[key] = state
        return state
    }

    /// One property group of `rc_project_clip_state`'s untyped reply, decoded
    /// through the same lenient path as the project itself.
    static func decode<T: Decodable>(_ type: T.Type, _ value: Any?) -> T? {
        guard let object = value, JSONSerialization.isValidJSONObject(object),
              let data = try? JSONSerialization.data(withJSONObject: object),
              let text = String(data: data, encoding: .utf8)
        else { return nil }
        return ReelJSON.decode(type, from: text)
    }

    func video(_ clip: ClipSnapshot) -> VideoProps {
        mode == .defaults ? .identity : evaluated(clip).video ?? clip.videoProps
    }
    func audio(_ clip: ClipSnapshot) -> AudioProps {
        mode == .defaults ? AudioProps() : evaluated(clip).audio ?? clip.audioProps
    }
    func text(_ clip: ClipSnapshot) -> TextProps {
        mode == .defaults ? TextProps() : evaluated(clip).text ?? clip.text ?? TextProps()
    }
    /// A graphic clip's props, evaluated (spec §11 G-34 (h), (l)); `.defaults`
    /// answers none, so every row reads its schema default.

Clicking a band also moves the playhead to the action's end, so the preview shows the state the Clip tab is editing (one frame short when the action ends with the clip).

Leaving the span keeps the action selected. To leave it, press **Esc**, click the **Clip** chip at the start of the action lane, or select a different clip. Only a single selected clip can have a selected action. Selecting an action is not an undo step and is not saved with the project.

### Edit an action's end state

While an action is selected, every field in the Clip tab shows and sets that action's **end state**, the values the clip reaches at the action's end. The same goes for the canvas: dragging the selected clip's handles writes the end state. The arrow keys don't nudge the clip; they move the playhead.

Unchecking a switch inside an action (a shadow or an outline, for example) turns that property off when the action ends.

The Clip tab marks each row so you can see what the action touches:

| Mark | Meaning |
|---|---|
| ◆ | This action animates the row. The label turns strong and the field gets a border in the action colour. A popup, checkbox or other on/off control also shows "at end", because it switches rather than ramps |
| ◇ | Another action on the clip animates this row. Its tooltip names the action |
| ○ | The row follows a value this action animates (for example, Gain follows Volume) |
| ⊘ | Actions don't animate this row. Edits change the clip |

A slider on an animated row fills in the action colour from the value at the action's start to the knob. When the playhead is inside the clip, a coral tick shows the value at the playhead. A row that is a field only shows that value as a "now …" tag instead.

Section headers carry the same marks, and a section where every row is ⊘ says "Actions don't animate this. Edits here change the clip." Each sub-tab's label shows **◆N** when the selected action animates N of its keys. When you select an action, the sections it animates on the current sub-tab open automatically.

To take a property back out of an action:

- Hover over a ◆ and click the × that replaces it ("Remove from action N").
- Click **Clear** in a section's header to remove all of that section's keys from the action. While an action is selected and keys the section, Clear takes the place of the header's **Reset**; otherwise Reset shows only while the section differs from its defaults.
- Right-click a row for its menu: **Remove from action N** on an animated row, **Go to action M** on a ◇ row (selects that action), and **Set end value to default** (on a row that can animate, while an action is selected) or **Reset to default** (otherwise). The default item is disabled when the row already holds its default.

*Agents:* `set_action_end` (a `patch` with `video`, `audio`, `text` and `graphic` groups and a top-level `speed`, merged into the end state; `null` removes a key; `off` lists `"group.key"` paths to switch off at the end). `video.motion` and `text.words` are refused.

